arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" }
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "Learn fundamental programming concepts using C#. Topics include variables, control flow, data structures, and object-oriented programming principles.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Bob Martinez",
            InstructorBio = "Dr. Martinez is a former Google engineer turned educator. His research focuses on algorithm optimization and computational complexity theory.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
        },
        new()
        {
            Id = 3, CourseCode = "CS 350", Title = "Software Engineering",
            Description = "Principles and practices of software development including agile methodologies, version control, testing strategies, and team collaboration.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Sarah Kim",
            InstructorBio = "Prof. Kim brings 20 years of industry experience from Microsoft and Amazon. She specializes in software architecture and development processes.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
        },
        new()
        {
            Id = 4, CourseCode = "MATH 101", Title = "Calculus I",
            Description = "Introduction to differential and integral calculus. Topics include limits, derivatives, integrals, and applications to real-world problems.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. James Wilson",
            InstructorBio = "Dr. Wilson is an award-winning mathematics educator with a passion for making calculus accessible to all students.",
            DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH 240", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues and eigenvectors, with applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Maria Lopez",
            InstructorBio = "Dr. Lopez is a researcher in applied mathematics whose work bridges pure mathematics and machine learning applications.",
            DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
        },
        new()
        {
            Id = 6, CourseCode = "ENG 110", Title = "Academic Writing",
            Description = "Develop skills in college-level writing including thesis development, argumentation, research methods, and proper citation practices.",
            Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. David Brown",
            InstructorBio = "Prof. Brown is a published author and writing instructor who has helped thousands of students find their academic voice.",
            DepartmentId = 3, DepartmentName = "English", IsFeatured = false
        },
        new()
        {
            Id = 7, CourseCode = "ENG 250", Title = "American Literature",
            Description = "Survey of American literature from the colonial period to the present, examining major works and literary movements in their historical context.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Emily Foster",
            InstructorBio = "Dr. Foster specializes in 20th-century American fiction and has published two books on the Harlem Renaissance.",
            DepartmentId = 3, DepartmentName = "English", IsFeatured = true
        },
        new()
        {
            Id = 8, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes lab component with hands-on experiments and data analysis.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Richard Park",
            InstructorBio = "Dr. Park is an experimental physicist whose research in particle physics has been conducted at CERN and Fermilab.",
            DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false
        },
        new()
        {
            Id = 9, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from antiquity through the Middle Ages, exploring political, social, and cultural developments across regions.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Catherine Reed",
            InstructorBio = "Dr. Reed is a medieval historian with archaeological fieldwork experience across Europe and the Middle East.",
            DepartmentId = 5, DepartmentName = "History", IsFeatured = false
        },
        new()
        {
            Id = 10, CourseCode = "HIST 320", Title = "Modern American History",
            Description = "America from Reconstruction to the present day, examining industrialization, civil rights, foreign policy, and cultural transformations.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Prof. Thomas Grant",
            InstructorBio = "Prof. Grant is a public historian who has consulted for the Smithsonian and authored several popular history books.",
            DepartmentId = 5, DepartmentName = "History", IsFeatured = true
        }
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);
}

